INSERT INTO documentos (coleccion, id, datos, orde) VALUES ('paxinas_libres', 'inicio', '{"titulo":"Inicio","nai":"","borrador":false,"seccions":[{"id":"sw7bwn","tipo":"heroe","oculta":false,"fondo":"claro","etiqueta":"#AFeira · IES Luís Seoane · Pontevedra","titulo":"A Feira non son dous días.","destaque":"É un movemento.","texto":"Dende 2023, a Feira da Sostibilidade converte o IES Luís Seoane nun laboratorio aberto onde o alumnado investiga, actúa e constrúe cidadanía crítica xunto a centros educativos, universidade e entidades sociais.","imaxe":"f-multitude-corredor","imaxeAlt":"Corredor do IES Luís Seoane cheo de xente durante a Feira","cifras":[{"valor":"4","etiqueta":"edicións celebradas"},{"valor":"+1.000","etiqueta":"persoas participantes por edición"},{"valor":"30","etiqueta":"entidades colaboradoras na IV edición"},{"valor":"13","etiqueta":"centros de Galicia, España e Europa"}],"botons":[{"texto":"V Feira · 28–30 abril 2027","url":"/edicions/2027/","estilo":"principal"},{"texto":"Que é a Feira","url":"#a-feira","estilo":"secundario"}]},{"id":"sxavm3","tipo":"texto_imaxe","oculta":false,"fondo":"branco","ancla":"a-feira","etiqueta":"A Feira","titulo":"E se un instituto puidese cambiar o mundo?","corpo":"<p>A Feira da Sostibilidade «Pensa, consume e actúa» naceu da iniciativa do colectivo <strong>Eco-Étika</strong>, formado por alumnado do IES Luís Seoane de Pontevedra. O <strong>IES Luís Seoane</strong> organízaa, e <strong>CIDEL Galicia</strong> e o <strong>Post-Growth Innovation Lab da Universidade de Vigo</strong> impúlsana e apóiana.</p><p>O instituto, no barrio de Monte Porreiro, abre as súas portas cada primavera a centros educativos, universidade, entidades sociais, administracións e veciñanza. O alumnado non presenta só resultados: comparte o que investigou, dinamiza actividades e constrúe propostas para o seu territorio.</p>","imaxe":"f-alumnado-presenta-investigacion","imaxeAlt":"Alumnado presentando os resultados dunha investigación cidadá","posicion":"dereita","botons":[{"texto":"Coñece FeiraLab","url":"/feiralab/","estilo":"secundario"}]},{"id":"syi3ek","tipo":"edicion_actual","oculta":false,"fondo":"claro","etiqueta":"Próxima edición"},{"id":"sz36ob","tipo":"tarxetas","oculta":false,"fondo":"verde","etiqueta":"FeiraLab","titulo":"Máis ca unha feira: un laboratorio.","texto":"Detrás da Feira hai un laboratorio de innovación educativa que traballa todo o curso con tres metodoloxías que se retroalimentan.","columnas":3,"items":[{"etiqueta":"ABP","titulo":"Investigar para comprender","texto":"O alumnado deseña e executa proxectos de investigación interdisciplinar sobre retos da Axenda 2030, conectando saberes científicos, sociais e artísticos.","url":"/feiralab/"},{"etiqueta":"ApS","titulo":"Actuar para transformar","texto":"O eixo que une aprendizaxe e acción comunitaria: o alumnado pon o seu coñecemento ao servizo da comunidade, con rede internacional con colectivos de Galicia e América Latina.","url":"/feiralab/"},{"etiqueta":"CC","titulo":"Investigar con rigor e impacto real","texto":"Co acompañamento científico da Universidade de Vigo, o alumnado convértese en investigador activo e conecta o local —o barrio de Monte Porreiro— co global.","url":"/feiralab/"}]},{"id":"s10mn8i","tipo":"edicions","oculta":false,"fondo":"claro","etiqueta":"As edicións","titulo":"Cada edición suma.","texto":"A Feira é un proceso vivo que medra cada curso: máis centros, máis entidades e máis proxectos do alumnado."},{"id":"s11tu3b","tipo":"cita","oculta":false,"fondo":"verde","texto":"O futuro non se explica.","destaque":"Constrúese."},{"id":"s12hj62","tipo":"noticias","oculta":false,"fondo":"branco","etiqueta":"Actualidade","titulo":"O proceso en directo.","numero":3},{"id":"s13bxuc","tipo":"galeria","oculta":false,"fondo":"claro","etiqueta":"IV Feira da Sostibilidade","titulo":"Así foi a última Feira.","imaxes":[{"imaxe":"f-stand-2","alt":"Stand número 2 da Feira con materiais do alumnado"},{"imaxe":"f-stand-alumnas","alt":"Alumnas explicando o seu stand a outras visitantes"},{"imaxe":"f-xogo-inclusivo","alt":"Nenas e nenos xogando a un xogo inclusivo no chan"},{"imaxe":"f-stand-4-ruleta","alt":"Stand con ruleta de xogo e voluntariado atendendo"},{"imaxe":"f-exposicion-carteis","alt":"Exposición de carteis no corredor"},{"imaxe":"f-stand-15","alt":"Posto 15 do alumnado con produtos de deseño propio"},{"imaxe":"f-obradoiro-mans","alt":"Mans traballando nun obradoiro"},{"imaxe":"f-charla-auditorio","alt":"Charla no salón de actos ante o alumnado"}]},{"id":"s144cn5","tipo":"logos","oculta":false,"fondo":"branco","etiqueta":"O ecosistema","titulo":"Unha rede que multiplica o impacto.","texto":"Entidades sociais, ONGD, cooperativas, administracións e iniciativas do territorio que fan a Feira posible.","grupos":[{"titulo":"Colaboran","entidades":["oxfam-intermon","adega","cogami","solidariedade-internacional","afectados-a57","ec4rural","cruz-vermella","feitoria-verde","galicia-ambiental","sig-comercio-xusto","casa-grande-de-xanceda","o-colmenar-de-sara","coxapo","aspanorcel","fundacion-balms","asociacion-boa-vida","aquelarre","ecoloxistas-en-accion","sembrando-bioxias"]}]},{"id":"s1572xo","tipo":"chamada","oculta":false,"fondo":"morado","etiqueta":"Participa","titulo":"Non veñas só mirar. Participa.","texto":"Centros educativos, entidades, empresas e medios: hai moitas formas de formar parte da Feira.","botons":[{"texto":"Como participar","url":"/participa/","estilo":"principal"},{"texto":"@feiradasostibilidade","url":"https://www.instagram.com/feiradasostibilidade","estilo":"secundario"}]}]}', -9);
INSERT INTO documentos (coleccion, id, datos, orde) VALUES ('paxinas_libres', 'participa', '{"titulo":"Participa","descricion":"Como participar na Feira da Sostibilidade: centros educativos, entidades, empresas, administracións e medios.","nai":"","borrador":false,"cabeceira":{"etiqueta":"Participa","titulo":"Non veñas só mirar.","destaque":"Participa.","texto":"A Feira constrúese entre moitas mans. Se queres participar, colaborar ou só saber máis, escríbenos.","datas":[{"data":"Xa","texto":"Inscricións abertas para centros e entidades"},{"data":"28–30 abril 2027","texto":"V Feira da Sostibilidade no IES Luís Seoane (Pontevedra)"}]},"seccions":[{"id":"perfis","tipo":"tarxetas","oculta":false,"fondo":"claro","columnas":4,"numerar":false,"items":[{"titulo":"Centros educativos","texto":"Trae á Feira o que investigou e creou o teu alumnado.","url":"/participa/?tipo=centro#formulario","boton":"Inscribir o centro"},{"titulo":"Entidades e colectivos","texto":"Comparte as túas propostas cun stand, un obradoiro ou unha charla.","url":"/participa/?tipo=entidade#formulario","boton":"Propoñer participación"},{"titulo":"Empresas e administracións","texto":"Colabora con experiencias, recursos ou espazos de diálogo.","url":"/participa/?tipo=entidade#formulario","boton":"Ofrecer colaboración"},{"titulo":"Prensa e medios","texto":"Información, imaxes e entrevistas sobre a Feira.","url":"/participa/?tipo=prensa#formulario","boton":"Contactar"}]},{"id":"formulario","tipo":"formulario","oculta":false,"fondo":"branco","ancla":"formulario","etiqueta":"Escríbenos","titulo":"Cóntanos que tes en mente.","texto":"Para participar ou simplemente preguntar: enche estes poucos campos e respondémosche axiña.","graciasTitulo":"Grazas! Recibimos a túa mensaxe.","graciasTexto":"Porémonos en contacto contigo nos próximos días."}]}', -8);
