INSERT INTO documentos (coleccion, id, datos, orde) VALUES ('paxinas_libres', 'recursos', '{"titulo":"Recursos","descricion":"Xogos, podcasts, estudos e materiais creados polo alumnado e o profesorado da Feira da Sostibilidade, en aberto.","nai":"","borrador":false,"cabeceira":{"etiqueta":"Recursos e produción","titulo":"O alumnado crea","destaque":"para compartir.","texto":"Xogos educativos, podcasts, investigacións de ciencia cidadá e materiais didácticos dispoñibles para outros centros e docentes.","datas":[]},"seccions":[{"id":"listado","tipo":"listado","oculta":false,"fondo":"claro","de":"recursos"}]}', -6);
INSERT INTO documentos (coleccion, id, datos, orde) VALUES ('paxinas_libres', 'edicions', '{"titulo":"Edicións","descricion":"Todas as edicións da Feira da Sostibilidade do IES Luís Seoane.","nai":"","borrador":false,"cabeceira":{"etiqueta":"As edicións","titulo":"Unha Feira cada abril.","destaque":"Un laboratorio que medra.","texto":"Cada edición suma coñecemento, amplía a rede e deixa materiais, memorias e aprendizaxes para a seguinte.","datas":[]},"seccions":[{"id":"listado","tipo":"listado","oculta":false,"fondo":"claro","de":"edicions"}]}', -5);
